$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-runtime-tail-20260914';$sha='24c4304a16a1665701d05444619d46b832c73e43'
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$controller='D:\projects\verify_current_package_protocol_r1.py';$config='D:\projects\AIMA-public-runtime-tail-20260914\build\current-package-http-config-r1.json'
$out='D:\projects\AIMA-public-runtime-tail-20260914\build\current-package-protocol-r1';$specPath=$out+'.json'
foreach($p in @($out,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
if((Get-FileHash $controller -Algorithm SHA256).Hash.ToLowerInvariant() -ne '5d8d13aa3fbd02deeb98dc3afd7b3ce8e89ee1ef60df4382b8522ac99618a436'){throw 'Controller changed'}
if((Get-FileHash $config -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'dfc4d67bfed4fcdd49aa950d925a018a2e65f4120db2cc0f4590b716b4761f28'){throw 'Package config changed'}
$spec=[ordered]@{executable='C:\Program Files\Python313\python.exe';arguments=@($controller);working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();controller_file=$controller;controller_sha256=(Get-FileHash $controller -Algorithm SHA256).Hash.ToLowerInvariant();config_sha256=(Get-FileHash $config -Algorithm SHA256).Hash.ToLowerInvariant();model='D:/models/Qwen3.6-35B-A3B';inference_acceptance=$false;purpose='Native extracted-archive chat/tool/thinking and queue timeout/overflow/shutdown tests; final active request retains complete frozen q8192 GB10 boundary'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds 720|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'HTTP protocol check failed'}

